export const VERIFIED_ARTIST_IMAGES_BY_ID: Record<string, string> = {};

/**
 * Normalizes a song title and artist into a lookup key.
 */
export function getArtworkKey(title?: string, artist?: string): string {
  if (!title || !artist) return '';
  return `${title.toLowerCase().trim()}---${artist.toLowerCase().trim()}`;
}

/**
 * Resolves verified authentic album or single cover art for a song.
 * Checks ID match first, then normalized title+artist key match.
 */
export function getVerifiedSongArtwork(song?: { id?: string; title?: string; artist?: string } | null): string | undefined {
  if (!song) return undefined;
  if (song.id && VERIFIED_SONG_ARTWORK_BY_ID[song.id]) {
    return VERIFIED_SONG_ARTWORK_BY_ID[song.id];
  }
  const key = getArtworkKey(song.title, song.artist);
  if (key && VERIFIED_SONG_ARTWORK_BY_KEY[key]) {
    return VERIFIED_SONG_ARTWORK_BY_KEY[key];
  }
  // Try partial primary artist match
  if (song.title && song.artist) {
    const primaryArtist = song.artist.split(/[,&/]|feat.?|ft.?/i)[0].trim().toLowerCase();
    const partialKey = `${song.title.toLowerCase().trim()}---${primaryArtist}`;
    if (VERIFIED_SONG_ARTWORK_BY_KEY[partialKey]) {
      return VERIFIED_SONG_ARTWORK_BY_KEY[partialKey];
    }
  }
  return undefined;
}

/**
 * Resolves verified artist profile image by artist ID.
 */
export function getVerifiedArtistImage(artistId?: string | null): string | undefined {
  if (!artistId) return undefined;
  return VERIFIED_ARTIST_IMAGES_BY_ID[artistId];
}
